-- A4: avg / p99 / total size of large text+jsonb columns
\echo == A4 column payloads
SELECT 'ai_request_payloads.request_body' col, count(*) n, pg_size_pretty(avg(octet_length(request_body::text))::bigint) avg, pg_size_pretty(percentile_cont(0.99) WITHIN GROUP (ORDER BY octet_length(request_body::text))::bigint) p99, pg_size_pretty(sum(octet_length(request_body::text))::bigint) total FROM ai_request_payloads
UNION ALL SELECT 'ai_request_payloads.response_body', count(*), pg_size_pretty(avg(octet_length(response_body::text))::bigint), pg_size_pretty(percentile_cont(0.99) WITHIN GROUP (ORDER BY octet_length(response_body::text))::bigint), pg_size_pretty(sum(octet_length(response_body::text))::bigint) FROM ai_request_payloads
UNION ALL SELECT 'ai_request_messages.content', count(*), pg_size_pretty(avg(octet_length(content))::bigint), pg_size_pretty(percentile_cont(0.99) WITHIN GROUP (ORDER BY octet_length(content))::bigint), pg_size_pretty(sum(octet_length(content))::bigint) FROM ai_request_messages
UNION ALL SELECT 'event_outbox.fact', count(*), pg_size_pretty(avg(octet_length(fact::text))::bigint), pg_size_pretty(percentile_cont(0.99) WITHIN GROUP (ORDER BY octet_length(fact::text))::bigint), pg_size_pretty(sum(octet_length(fact::text))::bigint) FROM event_outbox
UNION ALL SELECT 'logs.metadata', count(*), pg_size_pretty(avg(octet_length(metadata::text))::bigint), pg_size_pretty(percentile_cont(0.99) WITHIN GROUP (ORDER BY octet_length(metadata::text))::bigint), pg_size_pretty(sum(octet_length(metadata::text))::bigint) FROM logs
UNION ALL SELECT 'logs.message', count(*), pg_size_pretty(avg(octet_length(message))::bigint), pg_size_pretty(percentile_cont(0.99) WITHIN GROUP (ORDER BY octet_length(message))::bigint), pg_size_pretty(sum(octet_length(message))::bigint) FROM logs
UNION ALL SELECT 'governance_decisions.evaluated_rules', count(*), pg_size_pretty(avg(octet_length(evaluated_rules::text))::bigint), pg_size_pretty(percentile_cont(0.99) WITHIN GROUP (ORDER BY octet_length(evaluated_rules::text))::bigint), pg_size_pretty(sum(octet_length(evaluated_rules::text))::bigint) FROM governance_decisions
UNION ALL SELECT 'mcp_tool_executions.input+output', count(*), pg_size_pretty(avg(coalesce(octet_length(input),0)+coalesce(octet_length(output),0))::bigint), pg_size_pretty(percentile_cont(0.99) WITHIN GROUP (ORDER BY coalesce(octet_length(input),0)+coalesce(octet_length(output),0))::bigint), pg_size_pretty(sum(coalesce(octet_length(input),0)+coalesce(octet_length(output),0))::bigint) FROM mcp_tool_executions
UNION ALL SELECT 'ai_request_tool_calls.tool_input', count(*), pg_size_pretty(avg(octet_length(tool_input))::bigint), pg_size_pretty(percentile_cont(0.99) WITHIN GROUP (ORDER BY octet_length(tool_input))::bigint), pg_size_pretty(sum(octet_length(tool_input))::bigint) FROM ai_request_tool_calls
UNION ALL SELECT 'plugin_usage_events.metadata', count(*), pg_size_pretty(avg(octet_length(metadata::text))::bigint), pg_size_pretty(percentile_cont(0.99) WITHIN GROUP (ORDER BY octet_length(metadata::text))::bigint), pg_size_pretty(sum(octet_length(metadata::text))::bigint) FROM plugin_usage_events;
\echo == A4 payload bytes by request_kind (probes store full bodies too?)
SELECT r.request_kind, count(*) n, pg_size_pretty(sum(p.request_bytes)::bigint) req_bytes, pg_size_pretty(sum(p.response_bytes)::bigint) resp_bytes,
       pg_size_pretty(avg(p.request_bytes)::bigint) avg_req, count(*) FILTER (WHERE p.request_truncated) truncated
FROM ai_request_payloads p JOIN ai_requests r ON r.id = p.ai_request_id GROUP BY 1 ORDER BY 2 DESC;
\echo == A4 messages per request by kind
SELECT r.request_kind, count(DISTINCT r.id) requests, count(m.id) messages, round(count(m.id)::numeric/count(DISTINCT r.id),1) per_request
FROM ai_requests r LEFT JOIN ai_request_messages m ON m.request_id = r.id GROUP BY 1;
